{"code":"start_date = "2026-07-03"
end_date = "2026-10-01"

customer = get_customer("CUST-0100")
accounts = list_accounts("CUST-0100")
account_ids = [a["account_id"] for a in accounts]

balances = {aid: get_balance(aid) for aid in account_ids}
transactions = {aid: get_transactions(aid, start_date, end_date) for aid in account_ids}

result_accounts = []
total_available = 0.0

for acc in accounts:
    aid = acc["account_id"]
    bal = balances[aid]
    available = bal["available_balance"]
    total_available += available

    spend_by_category = {}
    large_debit_ids = []

    for tx in transactions[aid]:
        amount = tx["amount"]
        if amount < 0:
            abs_amount = abs(amount)
            cat = tx["category"]
            spend_by_category[cat] = round(spend_by_category.get(cat, 0.0) + abs_amount, 2)
            if abs_amount > 1000:
                large_debit_ids.append(tx["transaction_id"])

    # round spend values to 2 decimals
    spend_by_category = {k: round(v, 2) for k, v in spend_by_category.items()}
    large_debit_ids.sort()

    result_accounts.append({
        "account_id": aid,
        "available_balance": round(available, 2),
        "spend_by_category": spend_by_category,
        "large_debit_ids": large_debit_ids,
    })

total_available = round(total_available, 2)

output = {
    "customer_id": customer["customer_id"],
    "accounts": result_accounts,
    "total_available_balance": total_available,
}
print(output)"}
